use pulldown_cmark::{CodeBlockKind, Event, Options, Parser, Tag, TagEnd, html};
use std::cell::RefCell;
use std::collections::BTreeSet;

thread_local! {
    /// Class names written by the code components rendered so far on this thread. Tailwind cannot
    /// find them by scanning the sources (the numbers come from the articles), so the build writes
    /// them to a file that the stylesheet adds as a source.
    static GENERATED_CLASSES: RefCell<BTreeSet<String>> = const { RefCell::new(BTreeSet::new()) };
}

/// Returns, and forgets, the class names generated by `to_html` calls on this thread.
pub fn take_generated_classes() -> BTreeSet<String> {
    GENERATED_CLASSES.with(|classes| std::mem::take(&mut *classes.borrow_mut()))
}

/// Converts CommonMark text to an HTML fragment. Only one extension is enabled: tables.
/// Every code block (fenced or indented) becomes the code component: see `code_component`.
///
/// The closing note of a text is recognised too. If the last thematic break (`---`) of the
/// document is followed, up to the end, only by paragraphs, the break is dropped and those
/// paragraphs are wrapped in `<footer>`: the licence note at the end of an article. The
/// Markdown's own structure is the signal, as for code blocks, so the page knows it is a note and
/// the stylesheet does not have to guess from its position. `<footer>` because the note holds
/// data about the content, such as its licence. A break in the middle of the text, one followed
/// by anything else than paragraphs (a heading, list, code block, quote, table) and one at the
/// very end stay `<hr />`.
pub fn to_html(markdown: &str) -> String {
    let mut events: Vec<Event> = Vec::new();
    let mut open_block: Option<(Option<String>, String)> = None;
    for event in Parser::new_ext(markdown, Options::ENABLE_TABLES) {
        match event {
            Event::Start(Tag::CodeBlock(kind)) => {
                let language = match kind {
                    CodeBlockKind::Fenced(info) => info.split_whitespace().next().map(String::from),
                    CodeBlockKind::Indented => None,
                };
                open_block = Some((language, String::new()));
            }
            Event::Text(text) if open_block.is_some() => {
                if let Some((_, code)) = open_block.as_mut() {
                    code.push_str(&text);
                }
            }
            Event::End(TagEnd::CodeBlock) => {
                if let Some((language, code)) = open_block.take() {
                    events.push(Event::Html(
                        code_component(language.as_deref(), &code).into(),
                    ));
                }
            }
            other => events.push(other),
        }
    }
    wrap_closing_note(&mut events);
    let mut out = String::new();
    html::push_html(&mut out, events.into_iter());
    out
}

/// Applies the closing note rule of `to_html` to the events of a whole document.
fn wrap_closing_note(events: &mut Vec<Event>) {
    let mut depth = 0;
    let mut last_break = None;
    for (index, event) in events.iter().enumerate() {
        match event {
            Event::Start(_) => depth += 1,
            Event::End(_) => depth -= 1,
            Event::Rule if depth == 0 => last_break = Some(index),
            _ => {}
        }
    }
    let Some(break_index) = last_break else {
        return;
    };
    let mut depth = 0;
    let mut paragraphs = 0;
    for event in &events[break_index + 1..] {
        match event {
            Event::Start(Tag::Paragraph) if depth == 0 => {
                paragraphs += 1;
                depth += 1;
            }
            _ if depth == 0 => return,
            Event::Start(_) => depth += 1,
            Event::End(_) => depth -= 1,
            _ => {}
        }
    }
    if paragraphs == 0 {
        return;
    }
    events.push(Event::Html("</footer>\n".into()));
    events[break_index] = Event::Html("<footer>".into());
}

/// Advance width of every character of Hack, the code font, as a fraction of the font size:
/// 1233 / 2048 em (from the font's `hmtx` table, `unitsPerEm` 2048).
const CODE_ADVANCE_NUMERATOR: usize = 1233;
const CODE_ADVANCE_DENOMINATOR: usize = 2048;

/// Width in `em` of `n` characters of the code font, rounded up to 3 decimals (so the toggle may
/// show a hair early, never late) and written without trailing zeros ("3.613", "2.4").
fn code_width_em(n: usize) -> String {
    let thousandths = (n * CODE_ADVANCE_NUMERATOR * 1000).div_ceil(CODE_ADVANCE_DENOMINATOR);
    let whole = thousandths / 1000;
    let fraction = format!("{:03}", thousandths % 1000);
    let fraction = fraction.trim_end_matches('0');
    if fraction.is_empty() {
        whole.to_string()
    } else {
        format!("{whole}.{fraction}")
    }
}

/// Escapes the characters that mean something in HTML text and in a quoted attribute.
fn escape_html(out: &mut String, text: &str) {
    for c in text.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            other => out.push(other),
        }
    }
}

/// Columns of leading whitespace of a line (a tab goes to the next multiple of 4, because
/// Tailwind's base styles set `tab-size: 4`) and the line's length in columns, without its line
/// break.
fn indent_and_width(line: &str) -> (usize, usize) {
    let mut column = 0;
    let mut indent = None;
    for c in line.trim_end_matches(['\n', '\r']).chars() {
        if indent.is_none() && !matches!(c, ' ' | '\t') {
            indent = Some(column);
        }
        column = if c == '\t' {
            (column / 4 + 1) * 4
        } else {
            column + 1
        };
    }
    (indent.unwrap_or(column), column)
}

/// A code block as a component: the code keeps its lines and scrolls sideways inside its box;
/// a "wrap" toggle appears only when the longest line does not fit the box (the container query
/// `@max-[Wem]/code`, with W the width of the longest line, see `code_width_em`; `em` there is the code block's own
/// font size, so it holds at any text size. `em` and not `ch`, because Chromium does not evaluate `ch` again in a container query when
/// the web font arrives, so on a first visit the toggle could be wrong). Each line is a block of
/// its own carrying its indent, so a wrapped line continues 4 columns deeper than it starts. The
/// line break stays inside each line element, so the text of the code element is the block
/// unchanged.
/// The toggle is inside the scroller, otherwise the scroller is a scrollable region that
/// cannot be reached with the keyboard.
fn code_component(language: Option<&str>, code: &str) -> String {
    let mut classes = Vec::new();
    let mut longest = 0;
    let mut lines = String::new();
    for line in code.split_inclusive('\n') {
        let (indent, width) = indent_and_width(line);
        longest = longest.max(width);
        let indent_class = format!("code-line-indent-{indent}");
        lines.push_str(&format!("<span class=\"code-line {indent_class}\">"));
        escape_html(&mut lines, line);
        lines.push_str("</span>");
        classes.push(indent_class);
    }
    let mut block_class = String::from("code-block");
    if longest > 0 {
        let threshold_class = format!("@max-[{}em]/code:wrap-shown", code_width_em(longest));
        block_class.push(' ');
        block_class.push_str(&threshold_class);
        classes.push(threshold_class);
    }
    GENERATED_CLASSES.with(|all| all.borrow_mut().extend(classes));
    let language_class = match language {
        Some(name) => {
            let mut escaped = String::new();
            escape_html(&mut escaped, name);
            format!(" class=\"language-{escaped}\"")
        }
        None => String::new(),
    };
    format!(
        "<div class=\"{block_class}\"><div class=\"code-scroller\">\
<label class=\"code-wrap-toggle\"><input type=\"checkbox\" aria-label=\"Wrap long lines of code\"> wrap</label>\
<pre class=\"code-text\"><code{language_class}>{lines}</code></pre></div></div>\n"
    )
}

#[cfg(test)]
mod tests {
    use super::take_generated_classes;
    use super::to_html;
    use pulldown_cmark::{Event, Parser};

    #[test]
    fn converts_headings_and_lists() {
        let html = to_html("## A\n\n- b\n- c\n");
        assert!(html.contains("<h2>A</h2>"));
        assert!(html.contains("<li>b</li>"));
    }

    #[test]
    fn backslash_line_break_becomes_br() {
        assert!(to_html("a\\\nb").contains("a<br />\nb"));
    }

    #[test]
    fn table_becomes_table_with_header_and_data_cells() {
        let html = to_html("| a | b |\n|---|---|\n| c | d |\n");
        assert!(html.contains("<table>"));
        assert!(html.contains("<th>a</th>"));
        assert!(html.contains("<td>d</td>"));
    }

    #[test]
    fn closing_note_becomes_a_footer_without_the_break() {
        let html = to_html("A\n\n---\n\nThe licence.\n");
        assert!(html.contains("<footer>\n<p>The licence.</p>\n</footer>"));
        assert!(!html.contains("<hr"));
        assert!(html.contains("<p>A</p>"));
    }

    #[test]
    fn all_paragraphs_after_the_break_are_in_the_footer() {
        let html = to_html("A\n\n---\n\nOne.\n\nTwo.\n");
        let footer = &html[html.find("<footer>").unwrap()..];
        assert!(footer.contains("<p>One.</p>\n<p>Two.</p>\n</footer>"));
        assert_eq!(html.matches("<footer>").count(), 1);
    }

    #[test]
    fn break_in_the_middle_stays_a_rule() {
        let html = to_html("A\n\n---\n\nB.\n\n## H\n\nC.\n");
        assert!(html.contains("<hr />"));
        assert!(!html.contains("<footer"));
    }

    #[test]
    fn break_followed_by_a_heading_stays_a_rule() {
        let html = to_html("A\n\n---\n\n## H\n");
        assert!(html.contains("<hr />"));
        assert!(!html.contains("<footer"));
    }

    #[test]
    fn break_followed_by_other_blocks_stays_a_rule() {
        for tail in ["- a\n", "> q\n", "```\nx\n```\n", "| a |\n|---|\n| b |\n"] {
            let html = to_html(&format!("A\n\n---\n\nN.\n\n{tail}"));
            assert!(html.contains("<hr />"), "{tail}");
            assert!(!html.contains("<footer"), "{tail}");
        }
    }

    #[test]
    fn break_at_the_very_end_stays_a_rule() {
        let html = to_html("A\n\n---\n");
        assert!(html.contains("<hr />"));
        assert!(!html.contains("<footer"));
    }

    #[test]
    fn text_without_a_break_has_no_footer() {
        assert!(!to_html("A\n\nB\n").contains("<footer"));
    }

    #[test]
    fn inline_code_and_links_survive_in_the_closing_note() {
        let html = to_html("A\n\n---\n\nSee `x` and [site](https://example.org).\n");
        assert!(html.contains(
            "<footer>\n<p>See <code>x</code> and <a href=\"https://example.org\">site</a>.</p>\n</footer>"
        ));
    }

    #[test]
    fn inline_code_becomes_code() {
        assert!(to_html("`x`").contains("<code>x</code>"));
    }

    /// The author writes no raw HTML inside Markdown.
    #[test]
    fn curriculum_contains_no_raw_html() {
        for source in [
            include_str!("../content/curriculum.md"),
            include_str!("../content/licence.md"),
            include_str!("../content/about.md"),
            include_str!("../content/articles/after-save-event.md"),
            include_str!("../content/articles/how-to-generate-hybris-pk-values-without-hybris.md"),
        ] {
            let raw: Vec<Event> = Parser::new(source)
                .filter(|e| matches!(e, Event::Html(_) | Event::InlineHtml(_)))
                .collect();
            assert!(raw.is_empty(), "raw HTML found: {raw:?}");
        }
    }

    /// The text of the code element as the browser copies it: line wrappers removed, entities
    /// decoded.
    fn code_text(html: &str) -> String {
        let start = html.find("<code").unwrap();
        let start = start + html[start..].find('>').unwrap() + 1;
        let body = &html[start..html.find("</code>").unwrap()];
        let mut text = String::new();
        let mut rest = body;
        while let Some(open) = rest.find('<') {
            text.push_str(&rest[..open]);
            rest = &rest[rest.find('>').unwrap() + 1..];
        }
        text.push_str(rest);
        text.replace("&lt;", "<")
            .replace("&gt;", ">")
            .replace("&quot;", "\"")
            .replace("&amp;", "&")
    }

    #[test]
    fn fenced_code_becomes_the_component_with_its_language() {
        let html = to_html("```java\nint a;\n```\n");
        assert!(html.contains("<div class=\"code-block @max-[3.613em]/code:wrap-shown\">"));
        assert!(html.contains("<div class=\"code-scroller\"><label class=\"code-wrap-toggle\">"));
        assert!(html.contains("<input type=\"checkbox\" aria-label=\"Wrap long lines of code\"> wrap</label><pre class=\"code-text\"><code class=\"language-java\">"));
        assert!(html.contains("<span class=\"code-line code-line-indent-0\">int a;\n</span>"));
    }

    #[test]
    fn indented_code_is_a_component_without_language() {
        let html = to_html("text\n\n    x = 1\n");
        assert!(html.contains("<code><span"));
        assert!(html.contains("<div class=\"code-block @max-[3.011em]/code:wrap-shown\">"));
    }

    #[test]
    fn longest_line_is_counted_in_characters_not_bytes() {
        // "è" is two bytes, one character; the longest line is the second.
        let html = to_html("```\nèèè\nèèèè\n```\n");
        assert!(html.contains("@max-[2.409em]/code:wrap-shown"));
    }

    #[test]
    fn each_line_carries_its_own_indent() {
        let html = to_html("```\nfoo\n    bar\n  \n\tbaz\n```\n");
        assert!(html.contains("code-line-indent-0\">foo"));
        assert!(html.contains("code-line-indent-4\">    bar"));
        assert!(html.contains("code-line-indent-2\">  \n"));
        assert!(html.contains("code-line-indent-4\">\tbaz"));
    }

    #[test]
    fn code_is_escaped() {
        let html = to_html("```\n<b>&\"x\"</b>\n```\n");
        assert!(html.contains("&lt;b&gt;&amp;&quot;x&quot;&lt;/b&gt;"));
        assert!(!html.contains("<b>"));
    }

    #[test]
    fn copied_text_is_the_original_block() {
        let block = "line <one> & \"two\"\n    indented\n\n  last\n";
        let html = to_html(&format!("```xml\n{block}```\n"));
        assert_eq!(code_text(&html), block);
        assert!(!code_text(&html).contains("wrap"));
    }

    #[test]
    fn written_class_list_has_exactly_the_classes_used() {
        take_generated_classes();
        to_html("```\nab\n  cde\n```\n\n```\nxy\n```\n");
        let classes: Vec<String> = take_generated_classes().into_iter().collect();
        assert_eq!(
            classes,
            [
                "@max-[3.011em]/code:wrap-shown",
                "@max-[1.205em]/code:wrap-shown",
                "code-line-indent-0",
                "code-line-indent-2"
            ]
            .map(String::from)
            .iter()
            .cloned()
            .collect::<std::collections::BTreeSet<_>>()
            .into_iter()
            .collect::<Vec<_>>()
        );
        assert!(take_generated_classes().is_empty());
    }
}
